        print(line.strip())

names = ['Sam', 'Alexander', 'Jo', 'Priya', 'Bartholomew']
with open('names.txt', 'w') as f:
    for name in names:
        f.write(name + '\n')

with open('names.txt', 'r') as f:
    for line in f.readlines():
        name = line.strip()
        if len(name) > 4:
            print(name)

